#:property InvariantGlobalization=false

// Find the earliest Friday the 13th in the proleptic Gregorian calendar (from 0001-01-01)
// and count how many occur in a full 400-year cycle.

// --- Earliest Friday the 13th ---
var date = new DateTime(1, 1, 13); // start on the 13th of Jan 0001
while (date.DayOfWeek != DayOfWeek.Friday)
{
    date = date.AddMonths(1); // jump to the 13th of the next month
}
Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date.DayOfWeek})");

// --- Count in a full 400-year cycle (0001-01-01 to 0400-12-31) ---
int count = 0;
var current = new DateTime(1, 1, 13);
var end = new DateTime(400, 12, 31);

while (current <= end)
{
    if (current.DayOfWeek == DayOfWeek.Friday)
        count++;
    current = current.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F3}");

// --- Bonus: distribution by month ---
var byMonth = new int[12];
current = new DateTime(1, 1, 13);
while (current <= end)
{
    if (current.DayOfWeek == DayOfWeek.Friday)
        byMonth[current.Month - 1]++;
    current = current.AddMonths(1);
}

Console.WriteLine("\nDistribution by month:");
for (int m = 0; m < 12; m++)
    Console.WriteLine($"  {new DateTime(2000, m + 1, 1):MMMM,-12} {byMonth[m]}");

